action.command:
powershell -NoProfile -Command "
# Leer el workspace root desde stdin (JSON del contexto de Kiro)
$inputJson = $input | Out-String
$workspaceRoot = ''
try {
    $ctx = $inputJson | ConvertFrom-Json
    if ($ctx.workspaceRoot) { $workspaceRoot = $ctx.workspaceRoot }
    elseif ($ctx.workspace_root) { $workspaceRoot = $ctx.workspace_root }
    elseif ($ctx.cwd) { $workspaceRoot = $ctx.cwd }
} catch {}
if (-not $workspaceRoot -or -not (Test-Path $workspaceRoot)) {
    $workspaceRoot = (Get-Location).Path
}
$kiroDir = Join-Path $workspaceRoot '.kiro'
$chatPath = Join-Path $kiroDir 'contexto\CHAT.md'
$ontoBase = Join-Path $workspaceRoot 'NEVEN\docs\ontologia'
$output = @()
# --- CHAT.md ---
$output += '=== CONTEXTO DE SESIONES ANTERIORES (CHAT.md) ==='
$output += \"Workspace: $workspaceRoot\"
if (Test-Path $chatPath) {
    $chat = Get-Content $chatPath -Raw -Encoding UTF8
    $lines = $chat -split \"`n\"
    $recent = $lines | Select-Object -Last 150
    $output += $recent
    $output += ''
    $output += \"[CHAT.md cargado: $($lines.Count) lineas totales, mostrando ultimas 150]\"
} else {
    $output += '[CHAT.md no encontrado -- primera sesion del proyecto]'
}
$output += ''
# --- ONTOLOGIAS ---
$output += '=== ESPACIO DE ONTOLOGIAS ==='
# 1. NEVEN Core
$nevenCore = Join-Path $ontoBase 'neven-core'
if (Test-Path $nevenCore) {
    $output += ''
    $output += '[NEVEN-CORE] Ontologia de arquitectura del proyecto:'
    $files = @('neven-ontology-p1.yaml','neven-ontology-p2.yaml','neven-ontology-p3.yaml','neven-ontology-p4.yaml')
    foreach ($f in $files) {
        $path = Join-Path $nevenCore $f
        if (Test-Path $path) {
            $content = Get-Content $path -Raw
            $ids = [regex]::Matches($content, 'id:\s*(INV-[A-Z0-9-]+)') | ForEach-Object { $_.Groups[1].Value }
            $comp = [regex]::Matches($content, '- id:\s*([a-z_]+)\n\s+nombre:') | ForEach-Object { $_.Groups[1].Value }
            $output += \"  $f : $($comp.Count) componentes, $($ids.Count) invariantes\"
        }
    }
}
# 2. Econometrics
$econometrics = Join-Path $ontoBase 'econometrics'
if (Test-Path $econometrics) {
    $output += ''
    $output += '[ECONOMETRICS] Ontologia econometrica (grafo de conocimiento):'
    $graphFile = Join-Path $econometrics 'graph.jsonl'
    if (Test-Path $graphFile) {
        $nodes = (Get-Content $graphFile).Count
        $output += \"  graph.jsonl : $nodes nodos (Wooldridge, inferencia causal)\"
    }
    $aer = Join-Path $econometrics 'graph_aer_update.jsonl'
    $ts = Join-Path $econometrics 'graph_ts_update.jsonl'
    if (Test-Path $aer) { $output += \"  graph_aer_update.jsonl : $((Get-Content $aer).Count) nodos (AER)\" }
    if (Test-Path $ts) { $output += \"  graph_ts_update.jsonl : $((Get-Content $ts).Count) nodos (Series de Tiempo)\" }
    $output += '  Tipos: Method, Concept, Assumption, RFunction, Dataset'
}
# 3. Excel Functions
$excelFuncs = Join-Path $ontoBase 'excel-functions'
if (Test-Path $excelFuncs) {
    $output += ''
    $output += '[EXCEL-FUNCTIONS] Ontologia de funciones de Excel:'
    $excelFile = Join-Path $excelFuncs 'excel-functions-ontology.yaml'
    if (Test-Path $excelFile) {
        $content = Get-Content $excelFile -Raw
        $funcs = [regex]::Matches($content, '^\s+-\s+id:\s+\w+', [System.Text.RegularExpressions.RegexOptions]::Multiline)
        $cats = [regex]::Matches($content, '^funciones_\w+:', [System.Text.RegularExpressions.RegexOptions]::Multiline)
        $output += \"  excel-functions-ontology.yaml : $($funcs.Count) funciones, $($cats.Count) categorias\"
    }
}
$output += ''
$output += 'REGLAS ACTIVAS:'
$output += '- Consultar ontologia neven-core antes de cambios arquitecturales'
$output += '- Consultar ontologia econometrics para metodos estadisticos'
$output += '- Consultar ontologia excel-functions para referencia de funciones Excel'
$output += '- Actualizar CHAT.md al cerrar sesion'
$output -join \"`n\"
"
